from pathlib import Path
import re, json, hashlib
P=Path(__file__).resolve().parent
R=P/'reference'
def read(f):return json.loads(f.read_text())
def save(f,d):f.with_suffix('.tmp').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');f.with_suffix('.tmp').replace(f)
da=read(R/'modern-da.json');en=read(R/'modern-en.json');og=read(R/'original-en.json');records=[]
def setp(lang,n,i,value,why):
 ed={'da':da,'en':en}[lang]['chapters'][n-1]; old=ed['paragraphs'][i];assert old!=value
 records.append(dict(language=lang,unit=n,paragraphIndex=i,before=old,after=value,reason=why));ed['paragraphs'][i]=value
def edit(lang,n,i,old,new,why):
 s={'da':da,'en':en}[lang]['chapters'][n-1]['paragraphs'][i];assert s.count(old)==1,(n,i,old);setp(lang,n,i,s.replace(old,new),why)
setp('da',1,0,'Hvem har vel interesseret sig for menneskets historie og for, hvordan denne gådefulde blanding arter sig under tidens skiftende forsøg, uden at dvæle et øjeblik ved den hellige Teresas liv? Hvem har ikke smilet ømt ved tanken om den lille pige, der en morgen gik af sted hånd i hånd med sin endnu mindre bror for at søge martyrdøden i maurernes land? På små, usikre ben drog de ud af det barske Ávila, storøjede og tilsyneladende så hjælpeløse som to hjortekalve, men med menneskehjerter, der allerede slog for en hel nations idé. Så mødte de hjemmets virkelighed i skikkelse af deres onkler, som fik dem til at vende om og opgive deres store forehavende. Den lille pilgrimsfærd var en passende begyndelse. Teresas lidenskabelige higen efter det ideelle krævede et liv som et heltedigt. Hvad brød hun sig om tykke bind med ridderromaner eller om de sejre, en kvik ung pige kunne fejre i selskabslivet? Hendes ild fortærede hurtigt så let et brændsel. Den fik næring indefra og steg mod en opfyldelse uden grænser, mod et mål, hun aldrig med rette kunne blive træt af, og som kunne forsone hendes fortvivlelse over sig selv med fryden ved at mærke et liv ud over hendes eget. Hun fandt sit heltedigt i reformen af en klosterorden.','Restore the fawns, the toddlers’ steps and the sustained epic/fire imagery.')
setp('da',1,1,'Den spanske kvinde, der levede for tre hundrede år siden, var så vist ikke den sidste af sin slags. Mange Teresaer er født uden at finde et heltedigts liv, hvor den ene handling følger den anden og giver genlyd vidt omkring. Måske fik de kun et liv fuldt af fejltrin, født af en vis storhed i sindet, som deres trange kår gav alt for lidt spillerum. Måske led de et tragisk nederlag, som ingen digter besang, og som gled ubegrædt ind i glemslen. Med sparsomt lys at se ved og midt i et virvar af omstændigheder søgte de at bringe tanke og handling i ædel samklang. Men i andres øjne vidnede deres kamp kun om vægelsind og mangel på retning. For disse senere tiders Teresaer havde ingen fælles tro og samfundsorden, der kunne træde i stedet for viden hos et menneske, som brændte efter at handle. Deres glød svingede mellem et uklart ideal og de længsler, de delte med andre kvinder. Det ene måtte de høre for som overspændthed, det andet som et svigt.','Clarify the narrator’s movement from heroism to social constraint.')
setp('da',1,2,'Nogle har ment, at disse vildfarne liv skyldes den ubelejlige mangel på præcision, hvormed den højeste magt har udformet kvinders natur. Havde kvindelig uduelighed dog bare ét fast mål, så nøje bestemt som evnen til at tælle til tre og ikke længere, kunne man udtale sig om kvindens lod i samfundet med videnskabelig sikkerhed. Men det står stadig hen i det uvisse, og forskellene spænder i virkeligheden langt videre, end man skulle tro efter kvinders ensartede frisurer og de elskovshistorier på vers og prosa, der står i så høj kurs. Hist og her vokser en svaneunge op blandt ællingerne i den brune dam uden at falde til og finder aldrig ud i strømmen, hvor dens egne padler af sted. Hist og her fødes en hellig Teresa, som intet grundlægger. Hendes kærlige hjerteslag og hendes hulken af længsel efter en godhed, hun aldrig når, sitrer hen og fortaber sig mellem alle hindringerne i stedet for at samle sig i en handling, man længe efter ville kunne kende hende på.','Restore the mock-scientific voice, cygnet and ending cadence.')
setp('da',2,0,'Da jeg som kvinde intet godt kan gøre,\nrækker jeg altid efter det, der kommer godheden nær.\n—_The Maid’s Tragedy_, BEAUMONT OG FLETCHER.','Correct mistaken imperative and restore first-person perspective.')
setp('da',7,0,'Min frues tunge ligner engens strå,\nder skærer den, som stryger dem i tanker.\nHun har sin kunst i snittet: med sin ånds\nskarpe æg kan hun kløve selv et hirsekorn\nog spare summer, ingen hånd kan gribe.','Recover the cutting edge and satirical economies.')
setp('da',21,0,'»Et ene barn, der brat er vågnet op\nog ængsteligt ser rundt, hvorhen det kan,\nser kun, at det forgæves søger\net kærligt blik, som møder dets.«','Recover the absence of a loving gaze.')
setp('da',22,0,'»Hun talte smukt og ligefrem, som kvinder kan,\nog lånte ingen fine ord\nfor at gå for vis.«\n—CHAUCER.','Translate the retained Middle English epigraph.')
setp('da',53,0,'»Selv de ringeste pligter\npåtog han sig af sit gode hjerte.«\n—WORDSWORTH.','Convey voluntary service without the literal English inversion.')
setp('da',59,0,'»Intet had kan bo i dit blik,\nså dér kan jeg aldrig se, om du har forandret dig.\nHos mange står det falske hjertes historie\nskrevet i miner, rynkede bryn og sære furer.\nMen da du blev skabt, bestemte himlen,\nat øm kærlighed altid skulle bo i dit ansigt.\nHvad du end tænker, hvad der end rører sig i dit hjerte,\nvil dit ansigt kun tale om ømhed.«\n—SHAKESPEARE: _Sonetterne_.','Repair gender and recover the sonnet’s contrast between face and heart.')
setp('da',61,0,'Gode vendinger er da al ros værd, og det har de altid været.\n—_Fredsdommer Shallow_.','Restore Shallow’s sententious but speakable phrase.')
setp('da',84,0,'»Og nu godmorgen til vore vågnende sjæle,\nsom ingen frygt får til at vogte på hinanden.\nFor kærligheden råder over lysten til alt andet, øjet ser,\nog gør et lille kammer til den hele verden.«\n—DR. DONNE.','Recover the final room/world conceit and rhythm.')
for l,old,new in [('en','The Nephew as Uncle, turned tragic—monstrous!','‘Der Neffe als Onkel’ turned tragic—_ungeheuer!_'),('da','Nevøen som onkel, gjort tragisk — uhyrligt!','›Der Neffe als Onkel‹ som tragedie — _ungeheuer!_')]:
 edit(l,20,25,old,new,'Restore Naumann’s switch into German and the German play title.')
setp('da',38,87,'»Nej, slet ikke. Men når De nu er oppe, ville jeg være Dem taknemmelig, hvis De ville læse et par sider af Lowth højt for mig.«','Restore his request to be read aloud to.')
setp('da',43,1,'Kort efter sin hjemkomst fra bryllupsrejsen aflagde Lydgate et af sine lægebesøg på Lowick Manor. I et brev var han blevet bedt om selv at fastsætte et tidspunkt.','Replace the speaking letter with the source’s request.')
setp('da',54,31,'Snart sad de i dagligstuen med træpanelerne og fik te og ristet brød. Mere havde Raffles ikke lyst til så tidligt på dagen. Han var næsten lige sådan om morgenen som om aftenen, skønt hans vært havde forestillet sig noget andet. Måske nød han ligefrem at pine andre en smule mere, nu hvor hans humør ikke stod helt så højt. I morgenlyset virkede hans opførsel i hvert fald mere ubehagelig.','Restore the morning/evening joke and replace calques.')
edit('da',68,16,'at vinde bredere støtte ved','at vinde bredere støtte til det nye hospital ved','Restore which institution stands to gain.')
edit('da',86,0,'Mr. Højmodig','Mr. Hovmod','High-mind names a vice, not generosity.')
edit('da',86,0,'Mr.\nHøjmodig','Mr.\nHovmod','Keep the allegorical name consistent across the line break.')
setp('da',88,24,'Hendes fintmærkende sind blev ved at sætte fine spor, selv om de færreste fik øje på dem. Hendes rige natur løb, som den flod Kyros brød kraften af, ud i strømme, hvis navne ingen kendte vidt omkring. Men det var umuligt at måle, hvor langt virkningen af hendes liv bredte sig blandt dem, der omgav hende. For at det gode i verden vokser, skyldes til dels handlinger, som aldrig kommer i historiebøgerne. Og når det ikke står så ilde til med dig og mig, som det kunne have gjort, skylder vi det for en stor del de mange, som trofast levede deres liv i det skjulte og hviler i grave, ingen besøger.','Restore unhistoric acts, the river and the address to you and me.')
exec((P/'targeted.py').read_text())
for k,d in [('modern-da',da),('modern-en',en)]:save(P/(k+'.json'),d)
save(P/'changes.json',records)
